<?php
$from=(string)($_GET['from']??date('Y-01-01'));$cutoff=(string)($_GET['to']??date('Y-m-d'));$name=(string)($_GET['name']??'');$department=(string)($_GET['department']??'all');
$canChooseDepartment=canFilterBalanceDepartment($u);if(!$canChooseDepartment)$department='all';
$searched=($_GET['search']??'')==='1';$result=['items'=>[],'more'=>false,'page'=>1];$queryError=null;
if($searched)try{$result=searchBalanceSnapshots($u,$_GET);}catch(DomainException $ex){$queryError=$ex->getMessage();}
$snapshots=$result['items'];
?>
<p class="page-intro">Define los filtros y pulsa Consultar saldos. Las fechas deben pertenecer al mismo año. Haz clic en el nombre de cada funcionario para desplegar sus saldos. Se presenta el último saldo registrado de cada funcionario dentro del intervalo seleccionado, en páginas de 20 resultados. Quienes no tengan movimientos registrados en ese intervalo no aparecerán.</p>
<section class="panel form-panel"><form method="get" class="filter-form" data-balance-filters><input type="hidden" name="page" value="balances"><input type="hidden" name="search" value="1"><label>Fecha de inicio<input type="date" name="from" value="<?=e($from)?>" max="<?=date('Y-m-d')?>" required></label><label>Fecha final<input type="date" name="to" value="<?=e($cutoff)?>" max="<?=date('Y-m-d')?>" required></label><label>Nombres o apellidos<input name="name" value="<?=e($name)?>" maxlength="120" placeholder="Todos o parte del nombre"></label><?php if($canChooseDepartment): ?><label>Dependencia<select name="department"><option value="all">Todas las dependencias autorizadas</option><?php foreach(rows('SELECT id,name FROM departments ORDER BY name') as $dep): ?><option value="<?=$dep['id']?>" <?=$department===(string)$dep['id']?'selected':''?>><?=e($dep['name'])?></option><?php endforeach; ?></select></label><?php else: ?><input type="hidden" name="department" value="all"><label>Dependencia<input value="Todas las dependencias" readonly><small>Consulta de tus saldos personales, incluidos los registrados antes de un traslado.</small></label><?php endif; ?><button class="button secondary">Consultar saldos</button></form><p class="fine">Los filtros se combinan. Cada usuario conserva su alcance autorizado. Los jefes y suplentes solo pueden consultar información de sus periodos de designación. El historial comienza con su registro en la aplicación; no se reconstruyen saldos anteriores sin evidencia.</p></section>
<?php if(!$searched): ?><section class="panel form-panel"><p>Selecciona los criterios de consulta para mostrar los saldos.</p></section><?php return; endif; ?>
<?php if($queryError): ?><div class="alert error" role="alert"><?=e($queryError)?></div><?php return; endif; ?>
<nav aria-label="Páginas de saldos"><?php foreach(['Anterior'=>$result['page']>1?$result['page']-1:null,'Siguiente'=>$result['more']?$result['page']+1:null] as $label=>$number): if($number===null)continue; ?><a class="button secondary" href="/?<?=e(http_build_query(array_replace($_GET,['page'=>'balances','search'=>'1','results_page'=>$number])))?>"><?=e($label)?></a><?php endforeach; ?><p>Página <?=(int)$result['page']?></p></nav>
<?php foreach($snapshots as $snapshot): $balance=json_decode($snapshot['data'],true,512,JSON_THROW_ON_ERROR); ?>
<details class="panel balance-person"><summary><strong><?=e($balance['name'])?></strong><span><?=e($snapshot['department'])?> · Último movimiento hasta el corte: <?=e($snapshot['created_at'])?></span><small>Haz clic para mostrar u ocultar los saldos.</small></summary>
<div class="form-panel"><h3>Ordinario-Remunerado disponible por semestre</h3><?php foreach($balance['quotas'] as $semester=>$available): ?><p><?=e($semester)?>: <strong><?=e(hours($available))?></strong> de 25 h 30 min</p><?php endforeach; ?></div>
<div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Reservado / en trámite</th><th>Aprobado o disfrutado</th><th>Beneficio anual</th></tr></thead><tbody><?php foreach($balance['types'] as $type): ?><tr><td><?=e($type['name'])?><small><?=e(familyLabel($type['family']))?></small></td><td><?=e(hours($type['reserved']))?></td><td><?=e(hours($type['used']))?></td><td><?=e(implode(', ',$type['birthday_years']))?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="form-panel"><h3>Compensatorios por acto administrativo</h3><?php if(!$balance['acts']): ?><p>Sin actos aprobados a la fecha del registro.</p><?php endif; foreach($balance['acts'] as $act): ?><p><strong><?=e($act['number'])?></strong> · Otorgado: <?=e(hours($act['granted']))?> · Sin asignar: <?=e(hours($act['available']))?> · Vence: <?=e($act['expires_on'])?> <?=$act['expires_on']<$cutoff?'(vencido al corte)':''?></p><?php endforeach; ?></div></details>
<?php endforeach; if(!$snapshots): ?><section class="panel form-panel"><p>No hay registros de saldos disponibles para tu alcance y la fecha seleccionada.</p></section><?php endif; ?>
